const PLAN_OPTIONS: Array<{ key: TierFilter; label: string }> = [
  { key: "ALL", label: "All Tests" },
  { key: "FREE", label: "Free" },
  { key: "GOLD", label: "Standard" },
  { key: "PREMIUM", label: "Premium" },
];

const toTimestamp = (value: string) => new Date(value).getTime();

const buildFreeAccess = (assignments: ExamAssignment[]) => {
  const freeIds = new Set<string>();
  const sortedByCreatedAt = [...assignments].sort(
    (a, b) => toTimestamp(a.createdAt) - toTimestamp(b.createdAt),
  );

  const sectionUsage: Record<ExamSectionType, number> = {
    LISTENING: 0,
    READING: 0,
    WRITING: 0,
    SPEAKING: 0,
  };

  const fullMockGroups = new Map<string, ExamAssignment[]>();
  sortedByCreatedAt.forEach((assignment) => {
    if (!assignment.fullMockSessionId) {
      return;
    }

    const existing = fullMockGroups.get(assignment.fullMockSessionId) || [];
    existing.push(assignment);
    fullMockGroups.set(assignment.fullMockSessionId, existing);
  });

  const orderedFullMocks = [...fullMockGroups.entries()].sort(([, left], [, right]) => {
    const leftTime = Math.min(...left.map((assignment) => toTimestamp(assignment.createdAt)));
    const rightTime = Math.min(...right.map((assignment) => toTimestamp(assignment.createdAt)));
    return leftTime - rightTime;
  });

  orderedFullMocks.slice(0, FREE_FULL_MOCK_LIMIT).forEach(([, group]) => {
    group.forEach((assignment) => freeIds.add(assignment.id));
  });

  sortedByCreatedAt.forEach((assignment) => {
    const sectionType = assignment.section?.type;
    if (!sectionType) {
      return;
    }

    if (sectionUsage[sectionType] < FREE_TEST_LIMITS[sectionType]) {
      sectionUsage[sectionType] += 1;
      freeIds.add(assignment.id);
    }
  });

  return {
    freeIds,
    sectionUsage,
    freeFullMockCount: Math.min(orderedFullMocks.length, FREE_FULL_MOCK_LIMIT),
  };
};

export default function DashboardPage() {
  const { user, isLoading, isAuthenticated, logout } = useAuth();
  const queryClient = useQueryClient();
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
  const [selectedSection, setSelectedSection] = useState<DashboardSection>("FULL_ONLINE_MOCK");
  const [selectedPlan, setSelectedPlan] = useState<TierFilter>("ALL");
  const [isSectionPending, startSectionTransition] = useTransition();
  const [isPlanPending, startPlanTransition] = useTransition();
  const router = useRouter();

  const assignmentsQuery = useQuery({
    queryKey: studentQueryKeys.myAssignments(),
    queryFn: ({ signal }) => api.getMyAssignments({ signal }),
    enabled: !!user?.id,
    staleTime: STUDENT_QUERY_TIMINGS.assignments.staleTime,
    gcTime: STUDENT_QUERY_TIMINGS.assignments.gcTime,
    placeholderData: (previousData) => previousData,
  });

  const resultsQuery = useQuery({
    queryKey: studentQueryKeys.myResults(),
    queryFn: ({ signal }) => api.getMyResults({ signal }),
    enabled: !!user?.id,
    staleTime: STUDENT_QUERY_TIMINGS.results.staleTime,
    gcTime: STUDENT_QUERY_TIMINGS.results.gcTime,
    placeholderData: (previousData) => previousData,
  });

  const centerQuery = useQuery({
    queryKey: studentQueryKeys.center(user?.centerId || ""),
    queryFn: ({ signal }) => api.getCenter(user!.centerId!, { signal }),
    enabled: !!user?.centerId,
    staleTime: STUDENT_QUERY_TIMINGS.center.staleTime,
    gcTime: STUDENT_QUERY_TIMINGS.center.gcTime,
  });

  const profileQuery = useQuery({
    queryKey: studentQueryKeys.authProfile(),
    queryFn: ({ signal }) => api.getProfile({ signal }),
    enabled: !!user?.id,
    staleTime: STUDENT_QUERY_TIMINGS.profile.staleTime,
    gcTime: STUDENT_QUERY_TIMINGS.profile.gcTime,
    refetchOnWindowFocus: 'always',
    placeholderData: (previousData) => previousData,
  });

  const assignments = useMemo(
    () => assignmentsQuery.data ?? [],
    [assignmentsQuery.data],
  );
  const loadingAssignments = assignmentsQuery.isLoading && !assignmentsQuery.data;
  const centerLogo = centerQuery.data?.logo || null;
  const premiumProfile = profileQuery.data as (typeof profileQuery.data & PremiumFlags) | undefined;
  const isPremiumUser = Boolean(
    premiumProfile?.premiumActive ?? premiumProfile?.isPremium ?? false,
  );
  const isGoldUser = Boolean(premiumProfile?.goldActive ?? false) && !isPremiumUser;
  const userAccessTier: AccessTier = isPremiumUser
    ? "PREMIUM"
    : isGoldUser
      ? "GOLD"
      : "FREE";

  const freeAccess = useMemo(() => buildFreeAccess(assignments), [assignments]);
  const standaloneSubmittedAssignmentIds = useMemo(() => {
    const submitted = new Set<string>();

    (resultsQuery.data ?? []).forEach((result) => {
      const answers = (result.answers || {}) as Record<string, unknown>;
      const source = typeof answers._attemptSource === "string" ? answers._attemptSource : "";

      if (source && source !== "standalone") {
        return;
      }

      const assignmentId =
        typeof answers._assignmentId === "string" ? answers._assignmentId.trim() : "";
      if (assignmentId) {
        submitted.add(assignmentId);
      }
    });

    return submitted;
  }, [resultsQuery.data]);
  const assignmentTierById = useMemo(() => {
    const tierMap = new Map<string, AccessTier>();
    assignments.forEach((assignment) => {
      tierMap.set(assignment.id, freeAccess.freeIds.has(assignment.id) ? "FREE" : "PREMIUM");
    });
    return tierMap;
  }, [assignments, freeAccess.freeIds]);

  const canAccessTier = useCallback(
    (tier: AccessTier): boolean => {
      if (tier === "FREE") {
        return true;
      }

      if (tier === "GOLD") {
        return userAccessTier === "GOLD" || userAccessTier === "PREMIUM";
      }

      return userAccessTier === "PREMIUM";
    },
    [userAccessTier],
  );

  const fullOnlineCompletion = useMemo(() => {
    const completedAssignmentIds = new Set<string>();

    (resultsQuery.data ?? []).forEach((result) => {
      const answers = (result.answers || {}) as Record<string, unknown>;
      if (answers._attemptSource !== "full-online-mock") {
        return;
      }

      const assignmentId =
        typeof answers._assignmentId === "string" ? answers._assignmentId.trim() : "";
      if (assignmentId) {
        completedAssignmentIds.add(assignmentId);
      }
    });

    return {
      completedAssignmentIds,
    };
  }, [resultsQuery.data]);

  const isFullOnlineAssignmentCompleted = useCallback(
    (assignment: ExamAssignment | null): boolean => {
      if (!assignment) {
        return false;
      }

      if (fullOnlineCompletion.completedAssignmentIds.has(assignment.id)) {
        return true;
      }

      return false;
    },
    [fullOnlineCompletion.completedAssignmentIds],
  );

  const standaloneFullOnlineAssignmentsByType = useMemo(() => {
    const grouped: Record<FullOnlineMockSectionType, ExamAssignment[]> = {
      LISTENING: [],
      READING: [],
      WRITING: [],
    };

    assignments.forEach((assignment) => {
      if (assignment.fullMockSessionId) {
        return;
      }

      if (standaloneSubmittedAssignmentIds.has(assignment.id)) {
        return;
      }

      const type = assignment.section?.type;
      if (type === "LISTENING" || type === "READING" || type === "WRITING") {
        grouped[type].push(assignment);
      }
    });

    FULL_ONLINE_MOCK_SEQUENCE.forEach((type) => {
      grouped[type].sort((left, right) => {
        const leftTitleNumber = extractTestNumberFromTitle(left.section?.title);
        const rightTitleNumber = extractTestNumberFromTitle(right.section?.title);

        if (
          leftTitleNumber !== null &&
          rightTitleNumber !== null &&
          leftTitleNumber !== rightTitleNumber
        ) {
          return leftTitleNumber - rightTitleNumber;
        }

        if (leftTitleNumber !== null && rightTitleNumber === null) {
          return -1;
        }

        if (leftTitleNumber === null && rightTitleNumber !== null) {
          return 1;
        }

        return new Date(left.createdAt).getTime() - new Date(right.createdAt).getTime();
      });
    });

    return grouped;
  }, [assignments, standaloneSubmittedAssignmentIds]);

  const fullOnlineMockPackages = useMemo<FullOnlineMockPackage[]>(() => {
    const listeningAssignments = standaloneFullOnlineAssignmentsByType.LISTENING;
    const readingAssignments = standaloneFullOnlineAssignmentsByType.READING;
    const writingAssignments = standaloneFullOnlineAssignmentsByType.WRITING;
    const packageCount = Math.max(
      listeningAssignments.length,
      readingAssignments.length,
      writingAssignments.length,
    );

    const packages: FullOnlineMockPackage[] = [];

    for (let index = 0; index < packageCount; index += 1) {
      const assignmentsByType: Record<FullOnlineMockSectionType, ExamAssignment | null> = {
        LISTENING: listeningAssignments[index] || null,
        READING: readingAssignments[index] || null,
        WRITING: writingAssignments[index] || null,
      };

      const hasAnyAssignment = FULL_ONLINE_MOCK_SEQUENCE.some(
        (type) => assignmentsByType[type] !== null,
      );

      if (!hasAnyAssignment) {
        continue;
      }

      const sourceTitle =
        assignmentsByType.LISTENING?.section?.title ||
        assignmentsByType.READING?.section?.title ||
        assignmentsByType.WRITING?.section?.title ||
        "";
      const extractedOrder = extractTestNumberFromTitle(sourceTitle);

      const packageOrder = extractedOrder ?? index + 1;
      const packageKey = `online-full-${packageOrder}-${index}`;
      const latestTimestamp = Math.max(
        ...FULL_ONLINE_MOCK_SEQUENCE.map(
          (type) =>
            assignmentsByType[type] !== null
              ? new Date((assignmentsByType[type] as ExamAssignment).createdAt).getTime()
              : 0,
        ),
      );
      const completionByType: Record<FullOnlineMockSectionType, boolean> = {
        LISTENING: isFullOnlineAssignmentCompleted(assignmentsByType.LISTENING),
        READING: isFullOnlineAssignmentCompleted(assignmentsByType.READING),
        WRITING: isFullOnlineAssignmentCompleted(assignmentsByType.WRITING),
      };

      const nextAssignment =
        FULL_ONLINE_MOCK_SEQUENCE.map((type) => ({
          assignment: assignmentsByType[type],
          completed: completionByType[type],
        })).find(
          (entry): entry is { assignment: ExamAssignment; completed: boolean } =>
            Boolean(entry.assignment && !entry.completed),
        )?.assignment || null;

      const availableCount = FULL_ONLINE_MOCK_SEQUENCE.filter(
        (type) => assignmentsByType[type] !== null,
      ).length;
      const completedCount = FULL_ONLINE_MOCK_SEQUENCE.filter(
        (type) => assignmentsByType[type] !== null && completionByType[type],
      ).length;
      const started = completedCount > 0;
      const completed = availableCount > 0 && completedCount >= availableCount;

      packages.push({
        packageKey,
        packageOrder,
        latestTimestamp,
        assignmentsByType,
        nextAssignment,
        completionByType,
        started,
        completed,
      });
    }

    return packages.sort((left, right) => {
      if (left.packageOrder !== right.packageOrder) {
        return left.packageOrder - right.packageOrder;
      }
      return left.latestTimestamp - right.latestTimestamp;
    });
  }, [isFullOnlineAssignmentCompleted, standaloneFullOnlineAssignmentsByType]);

  const getFullOnlineMockTier = useCallback(
    (pkg: FullOnlineMockPackage): AccessTier => {
      return getTierByFullOnlineMockOrder(pkg.packageOrder);
    },
    [],
  );

  const getFullOnlineMockPrimaryAssignment = useCallback(
    (pkg: FullOnlineMockPackage): ExamAssignment | null => {
      for (const type of FULL_ONLINE_MOCK_SEQUENCE) {
        const assignment = pkg.assignmentsByType[type];
        if (assignment) {
          return assignment;
        }
      }

      return null;
    },
    [],
  );

  const handleFullOnlineMockAction = useCallback(
    async (pkg: FullOnlineMockPackage) => {
      const nextAssignment = pkg.nextAssignment;
      const primaryAssignment = getFullOnlineMockPrimaryAssignment(pkg);
      const targetAssignment = nextAssignment ?? (pkg.completed ? primaryAssignment : null);

      if (!targetAssignment) {
        router.push("/history");
        return;
      }

      const requiredTier = getFullOnlineMockTier(pkg);
      if (requiredTier !== "FREE" && !canAccessTier(requiredTier)) {
        const params = new URLSearchParams();
        if (targetAssignment.section?.title) {
          params.set("lockedTest", targetAssignment.section.title);
        }
        params.set("requiredTier", requiredTier.toLowerCase());
        router.push(`/pricing${params.toString() ? `?${params.toString()}` : ""}`);
        return;
      }

      try {
        const nav = navigator as Navigator & {
          keyboard?: { lock?: (keys: string[]) => Promise<void> };
          userActivation?: { isActive: boolean };
        };

        if (!nav.userActivation || nav.userActivation.isActive) {
          if (!document.fullscreenElement) {
            await document.documentElement.requestFullscreen();
          }

          if (nav.keyboard?.lock) {
            try {
              await nav.keyboard.lock(["Escape"]);
            } catch (lockError) {
              console.warn("Keyboard lock failed:", lockError);
            }
          }
        }
      } catch (error) {
        console.warn("Fullscreen request failed:", error);
      }

      const params = new URLSearchParams({
        onlineMock: "1",
      });
      const listeningId = pkg.assignmentsByType.LISTENING?.id;
      const readingId = pkg.assignmentsByType.READING?.id;
      const writingId = pkg.assignmentsByType.WRITING?.id;

      if (listeningId) {
        params.set("onlineMockListeningId", listeningId);
      }
      if (readingId) {
        params.set("onlineMockReadingId", readingId);
      }
      if (writingId) {
        params.set("onlineMockWritingId", writingId);
      }

      router.push(`/exam/${targetAssignment.id}?${params.toString()}`);
    },
    [
      canAccessTier,
      getFullOnlineMockTier,
      getFullOnlineMockPrimaryAssignment,
      router,
    ],
  );

  const getFullOnlineMockActionLabel = useCallback(
    (pkg: FullOnlineMockPackage): string => {
      const requiredTier = getFullOnlineMockTier(pkg);
      if (requiredTier !== "FREE" && !canAccessTier(requiredTier)) {
        return requiredTier === "GOLD" ? "Unlock Standard" : "Unlock Premium";
      }

      const nextAssignment = pkg.nextAssignment;
      if (!nextAssignment) {
        return pkg.completed ? "Practice Again" : "View Online Results";
      }

      return pkg.started ? "Continue Exam" : "Start Exam";
    },
    [canAccessTier, getFullOnlineMockTier],
  );

  const requestFullscreen = useCallback(async () => {
    try {
      const nav = navigator as Navigator & {
        keyboard?: { lock?: (keys: string[]) => Promise<void> };
        userActivation?: { isActive: boolean };
      };

      if (nav.userActivation && !nav.userActivation.isActive) {
        return;
      }

      if (!document.fullscreenElement) {
        await document.documentElement.requestFullscreen();
      }

      if (nav.keyboard?.lock) {
        try {
          await nav.keyboard.lock(["Escape"]);
        } catch (lockError) {
          console.warn("Keyboard lock failed:", lockError);
        }
      }
    } catch (error) {
      console.warn("Fullscreen request failed:", error);
    }
  }, []);

  const handleStartExamClick = useCallback(
    async (
      event: MouseEvent<HTMLAnchorElement>,
      assignmentId: string,
      requiresFullscreen: boolean,
      proctored?: boolean,
    ) => {
      event.preventDefault();
      if (requiresFullscreen) {
        await requestFullscreen();
      }
      const url = proctored
        ? `/exam/${assignmentId}?proctored=1`
        : `/exam/${assignmentId}`;
      router.push(url);
    },
    [requestFullscreen, router]
  );

  const handlePremiumLockedClick = useCallback(
    (assignment: ExamAssignment, requiredTier: "GOLD" | "PREMIUM" = "PREMIUM") => {
      const params = new URLSearchParams();
      if (assignment.section?.title) {
        params.set("lockedTest", assignment.section.title);
      }
      params.set("requiredTier", requiredTier.toLowerCase());
      router.push(`/pricing${params.toString() ? `?${params.toString()}` : ""}`);
    },
    [router],
  );

  const activeAssignments = useMemo(() => {
    const offlineFlowAssignments = assignments.filter((assignment) =>
      Boolean(assignment.fullMockSessionId),
    );

    if (offlineFlowAssignments.length === 0) {
      return [];
    }

    const groups = new Map<string, ExamAssignment[]>();

    offlineFlowAssignments.forEach((assignment) => {
      if (!assignment.fullMockSessionId) return;
      const existing = groups.get(assignment.fullMockSessionId) || [];
      existing.push(assignment);
      groups.set(assignment.fullMockSessionId, existing);
    });

    if (groups.size === 0) {
      return offlineFlowAssignments;
    }

    let selected: ExamAssignment[] | null = null;
    let latestTimestamp = 0;

    groups.forEach((group) => {
      const hasPending = group.some((item) => item.status !== "SUBMITTED");
      if (!hasPending) return;
      const groupLatest = Math.max(
        ...group.map((item) => new Date(item.createdAt).getTime()),
      );
      if (groupLatest > latestTimestamp) {
        latestTimestamp = groupLatest;
        selected = group;
      }
    });

    return selected ?? offlineFlowAssignments;
  }, [assignments]);

  const sortedAssignments = useMemo(() => {
    return [...assignments].sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
    );
  }, [assignments]);

  // Transform assignments into display items (complete + parts) for each section type
  const readingDisplayAssignments = useMemo(() => {
    const readingAssignments = assignments.filter(
      (a) =>
        a.section?.type === "READING" &&
        !a.fullMockSessionId &&
        !standaloneSubmittedAssignmentIds.has(a.id)
    );
    return transformAssignments(readingAssignments, "READING");
  }, [assignments, standaloneSubmittedAssignmentIds]);

  const listeningDisplayAssignments = useMemo(() => {
    const listeningAssignments = assignments.filter(
      (a) =>
        a.section?.type === "LISTENING" &&
        !a.fullMockSessionId &&
        !standaloneSubmittedAssignmentIds.has(a.id)
    );
    return transformAssignments(listeningAssignments, "LISTENING");
  }, [assignments, standaloneSubmittedAssignmentIds]);

  const writingDisplayAssignments = useMemo(() => {
    const writingAssignments = assignments.filter(
      (a) =>
        a.section?.type === "WRITING" &&
        !a.fullMockSessionId &&
        !standaloneSubmittedAssignmentIds.has(a.id)
    );
    return transformAssignments(writingAssignments, "WRITING");
  }, [assignments, standaloneSubmittedAssignmentIds]);

  const speakingDisplayAssignments = useMemo(() => {
    const speakingAssignments = assignments.filter(
      (a) => a.section?.type === "SPEAKING" && !a.fullMockSessionId
    );
    return transformAssignments(speakingAssignments, "SPEAKING");
  }, [assignments]);

  // Get tier for a display assignment based on full-test index
  const getDisplayItemTier = useCallback((displayItem: DisplayAssignment): AccessTier => {
    const sectionType = displayItem.displaySection.type;
    let allDisplayAssignments: DisplayAssignment[] = [];

    switch (sectionType) {
      case "READING":
        allDisplayAssignments = readingDisplayAssignments;
        break;
      case "LISTENING":
        allDisplayAssignments = listeningDisplayAssignments;
        break;
      case "WRITING":
        allDisplayAssignments = writingDisplayAssignments;
        break;
      case "SPEAKING":
        allDisplayAssignments = speakingDisplayAssignments;
        break;
    }

    const orderedFullAssignmentIds: string[] = [];
    for (const item of allDisplayAssignments) {
      if (!orderedFullAssignmentIds.includes(item.originalAssignmentId)) {
        orderedFullAssignmentIds.push(item.originalAssignmentId);
      }
    }

    const fullTestIndex = orderedFullAssignmentIds.indexOf(displayItem.originalAssignmentId);
    if (fullTestIndex === -1) {
      return "PREMIUM";
    }

    if (fullTestIndex < FREE_FULL_TEST_COUNT) {
      return "FREE";
    }

    if (fullTestIndex < GOLD_FULL_TEST_COUNT) {
      return "GOLD";
    }

    return "PREMIUM";
  }, [readingDisplayAssignments, listeningDisplayAssignments, writingDisplayAssignments, speakingDisplayAssignments]);

  // Get current section's display assignments based on selected section
  const currentSectionDisplayAssignments = useMemo(() => {
    switch (selectedSection) {
      case "READING":
        return readingDisplayAssignments;
      case "LISTENING":
        return listeningDisplayAssignments;
      case "WRITING":
        return writingDisplayAssignments;
      case "SPEAKING":
        return speakingDisplayAssignments;
      default:
        return [];
    }
  }, [selectedSection, readingDisplayAssignments, listeningDisplayAssignments, writingDisplayAssignments, speakingDisplayAssignments]);

  // Filter display assignments by plan
  const filteredDisplayAssignmentsByPlan = useMemo<Record<TierFilter, DisplayAssignment[]>>(() => {
    const all = currentSectionDisplayAssignments;

    const free: DisplayAssignment[] = [];
    const gold: DisplayAssignment[] = [];
    const premium: DisplayAssignment[] = [];

    for (const item of all) {
      const tier = getDisplayItemTier(item);
      if (tier === "FREE") {
        free.push(item);
      } else if (tier === "GOLD") {
        gold.push(item);
      } else {
        premium.push(item);
      }
    }

    const goldPlanItems = [...free, ...gold];
    const premiumPlanItems = [...goldPlanItems, ...premium];

    return {
      ALL: all,
      FREE: free,
      GOLD: goldPlanItems,
      PREMIUM: premiumPlanItems,
    };
  }, [currentSectionDisplayAssignments, getDisplayItemTier]);

  const filteredDisplayAssignments = filteredDisplayAssignmentsByPlan[selectedPlan];

  // Handle non-sectioned assignments (Full Mock flows and legacy sections)
  const sectionAssignmentsBySection = useMemo<Record<DashboardSection, ExamAssignment[]>>(() => {
    const fullMockAssignments: ExamAssignment[] = [];

    for (const assignment of sortedAssignments) {
      if (assignment.fullMockSessionId) {
        fullMockAssignments.push(assignment);
      }
    }

    return {
      FULL_ONLINE_MOCK: fullMockAssignments,
      OFFLINE_EXAM: fullMockAssignments,
      READING: [],
      LISTENING: [],
      WRITING: [],
      SPEAKING: [],
    };
  }, [sortedAssignments]);

  const sectionAssignments = sectionAssignmentsBySection[selectedSection];

  // Filter assignments by plan for non-Reading sections (legacy logic for Listening/Writing without parts)
  const filteredAssignmentsByPlan = useMemo<Record<TierFilter, ExamAssignment[]>>(() => {
    const free: ExamAssignment[] = [];
    const gold: ExamAssignment[] = [];
    const premium: ExamAssignment[] = [];

    for (const assignment of sectionAssignments) {
      if (assignmentTierById.get(assignment.id) === "PREMIUM") {
        premium.push(assignment);
      } else {
        free.push(assignment);
      }
    }

    const goldPlanItems = [...free, ...gold];
    const premiumPlanItems = [...goldPlanItems, ...premium];

    return {
      ALL: sectionAssignments,
      FREE: free,
      GOLD: goldPlanItems,
      PREMIUM: premiumPlanItems,
    };
  }, [assignmentTierById, sectionAssignments]);

  const filteredAssignments = filteredAssignmentsByPlan[selectedPlan];

  const displayedAssignments = useMemo(() => {
    if (
      selectedSection === "FULL_ONLINE_MOCK" ||
      selectedSection === "OFFLINE_EXAM"
    ) {
      return sectionAssignments;
    }

    return filteredAssignments;
  }, [filteredAssignments, sectionAssignments, selectedSection]);

  useEffect(() => {
    if (!isLoading && !isAuthenticated) {
      router.push("/login");
    }
  }, [isLoading, isAuthenticated, router]);

  useEffect(() => {
    router.prefetch("/feedback");
  }, [router]);

  useEffect(() => {
    if (!user?.id) {
      return;
    }

    void queryClient.prefetchQuery({
      queryKey: studentQueryKeys.myResults(),
      queryFn: ({ signal }) => api.getMyResults({ signal }),
      staleTime: STUDENT_QUERY_TIMINGS.results.staleTime,
      gcTime: STUDENT_QUERY_TIMINGS.results.gcTime,
    });
  }, [queryClient, user?.id]);

  if (isLoading || !isAuthenticated) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-black"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      {/* Header */}
      <header className="sticky top-0 z-40 border-b border-gray-200 bg-white/95 backdrop-blur">
        <div className="max-w-7xl mx-auto px-4 py-4 flex flex-wrap items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="w-40 h-14 rounded-xl flex items-center justify-center">
              {centerLogo ? (
                <Image
                  src={centerLogo}
                  alt="Center Logo"
                  width={160}
                  height={56}
                  loading="eager"
                  className="max-h-14 h-auto w-auto object-contain"
                />
              ) : (
                <Image
                  src="/logo.png"
                  alt="logo"
                  width={160}
                  height={56}
                  loading="eager"
                  className="max-h-14 h-auto w-auto object-contain"
                />
              )}
            </div>
          </div>

          <nav className="order-3 w-full md:order-2 md:w-auto">
            <ul className="flex items-center justify-start gap-2 md:gap-4">
              <li>
                <Link
                  href="/dashboard"
                  className="inline-flex rounded-lg bg-black px-3 py-2 text-sm font-medium text-white"
                >
                  Dashboard
                </Link>
              </li>
              <li>
                <Link
                  href="/feedback"
                  className="inline-flex rounded-lg px-3 py-2 text-sm font-medium text-gray-600 transition-colors hover:bg-gray-100 hover:text-gray-900"
                >
                  Offline Results
                </Link>
              </li>
              <li>
                <Link
                  href="/history"
                  className="inline-flex rounded-lg px-3 py-2 text-sm font-medium text-gray-600 transition-colors hover:bg-gray-100 hover:text-gray-900"
                >
                  Online Results
                </Link>
              </li>
              <li>
                <Link
                  href="/pricing"
                  className="inline-flex rounded-lg px-3 py-2 text-sm font-medium text-gray-600 transition-colors hover:bg-gray-100 hover:text-gray-900"
                >
                  Pricing
                </Link>
              </li>
            </ul>
          </nav>

          <div className="order-2 md:order-3 flex items-center gap-4">
            <span className="text-gray-600">
              Welcome, {user?.firstName || user?.username}
            </span>
            <button
              onClick={() => setIsLogoutModalOpen(true)}
              className="px-4 py-2 rounded-lg bg-gray-100 text-gray-700 hover:bg-gray-200 transition-colors text-sm font-medium"
            >
              Sign Out
            </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto w-full px-4 py-8">
        <div className="space-y-2">
          <div className="sticky top-[84px] z-30 space-y-3 bg-gray-50/95 pb-2 backdrop-blur">
            <section className="rounded-3xl border border-gray-200 bg-white p-4 shadow-sm md:p-5">
              <div className="flex items-center justify-between px-1">
                <p className="text-xs font-semibold uppercase tracking-wide text-gray-500">
                  Sections
                </p>
                {isSectionPending && (
                  <span className="text-[10px] font-semibold uppercase tracking-wide text-gray-400">
                    Updating
                  </span>
                )}
              </div>

              <div className="mt-4 grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-6">
                {SECTION_CARD_ORDER.map((sectionKey) => {
                  const section = SECTION_OPTIONS.find((entry) => entry.key === sectionKey);
                  if (!section) {
                    return null;
                  }

                  const isActive = selectedSection === section.key;

                  return (
                    <button
                      key={section.key}
                      type="button"
                      disabled={section.comingSoon || isSectionPending}
                      onClick={() =>
                        startSectionTransition(() => {
                          setSelectedSection(section.key);
                          if (
                            section.key === "READING" ||
                            section.key === "LISTENING" ||
                            section.key === "WRITING" ||
                            section.key === "SPEAKING"
                          ) {
                            setSelectedPlan("ALL");
                          }
                        })
                      }
                      className={`rounded-2xl border px-4 py-4 text-center transition-all ${isActive
                        ? "border-(--button-brand-color) bg-(--button-brand-color) text-white shadow-sm"
                        : section.comingSoon
                          ? "cursor-not-allowed border-gray-200 bg-gray-100 text-gray-400"
                          : "border-gray-200 bg-gray-50 text-gray-700 hover:border-gray-300 hover:bg-white"
                        }`}
                    >
                      <div className="flex items-center justify-center gap-3">
                        <span
                          className={`inline-flex h-12 w-12 shrink-0 items-center justify-center rounded-xl ${isActive ? "bg-white/20" : "bg-white"
                            }`}
                        >
                          {renderSectionIcon(section.key, isActive)}
                        </span>
                      </div>

                      <p className="mt-3 text-sm font-semibold leading-tight">{section.label}</p>
                      {section.comingSoon && (
                        <p className="mt-1 text-[10px] uppercase tracking-wider">Coming soon</p>
                      )}
                    </button>
                  );
                })}
              </div>
            </section>

            {selectedSection !== "FULL_ONLINE_MOCK" &&
              selectedSection !== "OFFLINE_EXAM" &&
              selectedSection !== "SPEAKING" && (
                <div className="grid grid-cols-2 gap-1 rounded-2xl border border-gray-200 bg-white p-1 shadow-sm sm:grid-cols-4">
                  {PLAN_OPTIONS.map((plan) => {
                    const activePlan = selectedPlan === plan.key;
                    return (
                      <button
                        key={plan.key}
                        type="button"
                        disabled={isPlanPending}
                        onClick={() =>
                          startPlanTransition(() => {
                            setSelectedPlan(plan.key);
                          })
                        }
                        className={`rounded-xl px-3 py-2 text-sm font-medium transition-colors ${activePlan
                          ? "bg-black text-white"
                          : "text-gray-600 hover:bg-gray-100"
                          }`}
                      >
                        {plan.label}
                      </button>
                    );
                  })}
                </div>
              )}
          </div>

          <div>

            {loadingAssignments ? (
              <div className="flex items-center justify-center py-12">
                <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-black"></div>
              </div>
            ) : (
              <>
                {(selectedSection === "READING" || selectedSection === "LISTENING" || selectedSection === "WRITING"
                  ? filteredDisplayAssignments.length === 0
                  : selectedSection === "FULL_ONLINE_MOCK"
                    ? fullOnlineMockPackages.length === 0
                    : selectedSection === "SPEAKING"
                      ? false
                      : displayedAssignments.length === 0) ? (
                  <div className="text-center py-12">
                    <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-gray-800 flex items-center justify-center">
                      <svg
                        className="w-8 h-8 text-gray-600"
                        fill="none"
                        stroke="currentColor"
                        viewBox="0 0 24 24"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                        />
                      </svg>
                    </div>
                    <p className="text-gray-400">
                      {selectedSection === "FULL_ONLINE_MOCK"
                        ? "No tests found in Full Online Mock"
                        : selectedSection === "OFFLINE_EXAM"
                          ? "No tests found in Offline Exam"
                          : selectedSection === "READING"
                            ? "No reading tests available"
                            : selectedSection === "LISTENING"
                              ? "No listening tests available"
                              : selectedSection === "WRITING"
                                ? "No writing tests available"
                                : selectedSection === "SPEAKING"
                                  ? "No speaking tests available"
                                  : "No tests found for this filter"}
                    </p>
                    <p className="text-gray-500 text-sm mt-1">
                      {selectedSection === "FULL_ONLINE_MOCK" ||
                        selectedSection === "OFFLINE_EXAM"
                        ? "Try another section."
                        : "Tests will appear here once assigned."}
                    </p>
                  </div>
                ) : (
                  <>
                    {selectedSection === "FULL_ONLINE_MOCK" && (
                      <div className="mt-2 mb-8">
                        <div className="rounded-3xl border border-gray-200 bg-white p-6 shadow-sm">
                          <div className="flex items-center justify-between gap-4">
                            <h3 className="text-xl font-bold text-gray-900">Full Online Mock Tests</h3>
                            <p className="text-sm text-gray-500">{fullOnlineMockPackages.length} total</p>
                          </div>

                          <div className="mt-6 space-y-4">
                            {fullOnlineMockPackages.map((pkg) => {
                              const packageAssignments = pkg.assignmentsByType;
                              const packageTier = getFullOnlineMockTier(pkg);
                              const requiresUpgrade =
                                packageTier !== "FREE" && !canAccessTier(packageTier);
                              const packageActionLabel = getFullOnlineMockActionLabel(pkg);
                              const hasAnyAssignment = FULL_ONLINE_MOCK_SEQUENCE.some(
                                (type) => Boolean(packageAssignments[type]),
                              );
                              const titleSource =
                                packageAssignments.LISTENING?.section?.title ||
                                packageAssignments.READING?.section?.title ||
                                packageAssignments.WRITING?.section?.title ||
                                "";
                              const testMatch = titleSource.match(/test\s*\d+/i);
                              const packageTitle = testMatch
                                ? `Full Online Mock (${testMatch[0].replace(/\s+/g, " ").trim()})`
                                : `Full Online Mock ${pkg.packageOrder}`;

                              return (
                                <div key={pkg.packageKey} className="rounded-2xl border border-gray-200 p-4">
                                  <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
                                    <div>
                                      <div className="flex flex-wrap items-center gap-2">
                                        <p className="text-xs font-semibold uppercase tracking-widest text-gray-400">
                                          FULL ONLINE MOCK
                                        </p>
                                        <span
                                          className={`inline-flex rounded-lg px-2.5 py-1 text-[11px] font-semibold uppercase tracking-wide ${getFullOnlineMockTariffBadgeStyles(packageTier)}`}
                                        >
                                          {FULL_ONLINE_MOCK_TARIFF_LABELS[packageTier]}
                                        </span>
                                      </div>

                                      <h4 className="mt-1 text-lg font-semibold text-gray-900">
                                        {packageTitle}
                                      </h4>
                                      <div
                                        className="mt-2 flex items-center gap-2"
                                        aria-label="Listening, Reading, and Writing full test"
                                      >
                                        {FULL_ONLINE_MOCK_SEQUENCE.map((type) => (
                                          <span
                                            key={`${pkg.packageKey}:full-online-icon:${type}`}
                                            className={`inline-flex items-center justify-center rounded-xl border border-gray-200 bg-white ${
                                              type === "READING" ? "h-9 w-9" : "h-8 w-8"
                                            }`}
                                          >
                                            {renderSectionIcon(type, false)}
                                          </span>
                                        ))}
                                      </div>

                                    </div>

                                    <div className="flex flex-wrap items-center gap-2">
                                      <button
                                        type="button"
                                        onClick={() => {
                                          void handleFullOnlineMockAction(pkg);
                                        }}
                                        disabled={!hasAnyAssignment}
                                        className={`inline-flex rounded-lg px-4 py-2 text-sm font-medium transition-colors ${requiresUpgrade
                                          ? "bg-amber-500 text-white hover:bg-amber-600"
                                          : "bg-black text-white hover:bg-gray-800"
                                          }`}
                                      >
                                        {packageActionLabel}
                                      </button>

                                      {pkg.completed && (
                                        <button
                                          type="button"
                                          onClick={() => {
                                            router.push("/history");
                                          }}
                                          className="inline-flex rounded-lg border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-700 transition-colors hover:bg-gray-100"
                                        >
                                          View Online Results
                                        </button>
                                      )}
                                    </div>
                                  </div>
                                </div>
                              );
                            })}
                          </div>
                        </div>
                      </div>
                    )}

                    {selectedSection === "SPEAKING" && (
                      <div className="mt-2 mb-12 w-full">
                        <div className="rounded-3xl border border-gray-200 bg-white p-8 shadow-sm">
                          <div className="mx-auto max-w-2xl text-center">
                            <p className="text-xs font-semibold uppercase tracking-[0.2em] text-gray-500">
                              Speaking Practice
                            </p>
                            <h3 className="mt-3 text-2xl font-bold text-(--button-brand-color)">
                              IELTS Speaking AI Examiner
                            </h3>
                            <p className="mt-3 text-sm leading-6 text-gray-600">
                              Use our Speaking Bot for guided prompts, timed responses, and daily speaking drills.
                              Your Telegram speaking workflow is separate from dashboard test sections.
                            </p>
                            <div className="mt-7">
                              <a
                                href="https://t.me/FoundersSpeakingBot"
                                target="_blank"
                                rel="noopener noreferrer"
                                className="inline-flex items-center gap-2 rounded-xl bg-(--button-brand-color) px-5 py-3 text-sm font-semibold text-white transition-colors hover:bg-(--button-brand-hover-color)"
                              >
                                <svg className="h-5 w-5" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                                  <path d="M9.03 15.71 8.7 20.37c.48 0 .69-.21.94-.46l2.24-2.14 4.65 3.4c.85.47 1.45.22 1.68-.79l3.04-14.27.01-.01c.27-1.26-.45-1.75-1.28-1.44L1.96 11.53c-1.23.48-1.21 1.17-.21 1.48l4.6 1.43L17.03 7.7c.5-.33.96-.15.58.18" />
                                </svg>
                                Open Telegram
                              </a>
                            </div>
                          </div>
                        </div>
                      </div>
                    )}

                    {selectedSection === "OFFLINE_EXAM" && (
                      <div className="max-w-6xl mx-auto mt-12 px-4">
                        <div className="bg-white rounded-4xl border border-gray-100 p-12 shadow-sm">
                          <div className="flex items-center justify-between relative px-4 mb-20">
                            {/* Background Connecting Line */}
                            <div className="absolute top-6 left-[10%] right-[10%] h-px bg-gray-200 z-0" />

                            {(() => {
                              const orderedTypes = ["LISTENING", "READING", "WRITING"];
                              const nextToComplete = orderedTypes.find((type) => {
                                const a = activeAssignments.find(
                                  (assignment) => assignment.section?.type === type,
                                );
                                return a && a.status !== "SUBMITTED";
                              });

                              return orderedTypes.map((type, idx) => {
                                const assignment = activeAssignments.find(
                                  (item) => item.section?.type === type,
                                );
                                const isCompleted = assignment?.status === "SUBMITTED";
                                const isActive = type === nextToComplete;
                                const stepNum = idx + 1;

                                return (
                                  <div
                                    key={type}
                                    className="flex flex-col items-center relative z-10 bg-white px-4"
                                  >
                                    {/* Step Circle */}
                                    <div
                                      className={`
                                w-12 h-12 rounded-full flex items-center justify-center border-2 transition-all duration-300
                                ${isCompleted
                                          ? "bg-black border-black text-white"
                                          : isActive
                                            ? "bg-white border-black text-black shadow-[0_0_0_4px_rgba(0,0,0,0.05)]"
                                            : "bg-white border-gray-200 text-gray-400"
                                        }
                              `}
                                    >
                                      {isCompleted ? (
                                        <svg
                                          className="w-6 h-6"
                                          fill="none"
                                          stroke="currentColor"
                                          viewBox="0 0 24 24"
                                        >
                                          <path
                                            strokeLinecap="round"
                                            strokeLinejoin="round"
                                            strokeWidth={3}
                                            d="M5 13l4 4L19 7"
                                          />
                                        </svg>
                                      ) : (
                                        <span className="text-lg font-bold">{stepNum}</span>
                                      )}
                                    </div>

                                    {/* Step Label */}
                                    <div className="absolute -bottom-10 whitespace-nowrap text-center">
                                      <p
                                        className={`text-sm font-bold uppercase tracking-widest ${isCompleted || isActive
                                          ? "text-black"
                                          : "text-gray-400"
                                          }`}
                                      >
                                        {type}
                                      </p>
                                      {assignment?.section?.duration && (
                                        <p className="text-[10px] text-gray-400 font-medium mt-0.5">
                                          {assignment.section.duration} MINS
                                        </p>
                                      )}
                                    </div>
                                  </div>
                                );
                              });
                            })()}
                          </div>

                          <div className="flex flex-col items-center gap-6 mt-16 pt-8 border-t border-gray-50">
                            {(() => {
                              const orderedTypes = ["LISTENING", "READING", "WRITING"];
                              const nextAssignment = orderedTypes
                                .map((type) =>
                                  activeAssignments.find(
                                    (assignment) => assignment.section?.type === type,
                                  ),
                                )
                                .find((assignment) => assignment && assignment.status !== "SUBMITTED");

                              if (nextAssignment) {
                                const nextTier =
                                  assignmentTierById.get(nextAssignment.id) || "FREE";
                                const requiresUpgrade = !canAccessTier(nextTier);

                                return (
                                  <>
                                    <div className="text-center mb-2">
                                      <h3 className="text-xl font-bold text-gray-900">
                                        Ready to start your{" "}
                                        {nextAssignment.section?.type.toLowerCase()}?
                                      </h3>
                                      <p className="text-gray-500 text-sm mt-1">
                                        Please ensure you are in a quiet environment.
                                      </p>
                                    </div>
                                    {requiresUpgrade ? (
                                      <button
                                        type="button"
                                        onClick={() =>
                                          handlePremiumLockedClick(
                                            nextAssignment,
                                            nextTier === "GOLD" ? "GOLD" : "PREMIUM",
                                          )
                                        }
                                        className="px-10 py-4 rounded-full bg-amber-500 text-white font-bold text-lg hover:bg-amber-600 transition-all shadow-xl shadow-amber-500/20"
                                      >
                                        {nextTier === "GOLD" ? "Unlock Standard" : "Unlock Premium"}
                                      </button>
                                    ) : (
                                      <Link
                                        href={`/exam/${nextAssignment.id}`}
                                        onClick={(event) =>
                                          handleStartExamClick(event, nextAssignment.id, true)
                                        }
                                        className="px-20 py-5 rounded-full bg-black text-white font-bold text-lg hover:bg-gray-800 transition-all shadow-xl shadow-black/10 hover:scale-[1.02] active:scale-[0.98] group flex items-center gap-3"
                                      >
                                        {nextAssignment.status === "IN_PROGRESS"
                                          ? "Continue Exam"
                                          : "Start Exam"}
                                        <svg
                                          className="w-5 h-5 group-hover:translate-x-1 transition-transform"
                                          fill="none"
                                          stroke="currentColor"
                                          viewBox="0 0 24 24"
                                        >
                                          <path
                                            strokeLinecap="round"
                                            strokeLinejoin="round"
                                            strokeWidth={2}
                                            d="M17 8l4 4m0 0l-4 4m4-4H3"
                                          />
                                        </svg>
                                      </Link>
                                    )}
                                  </>
                                );
                              }

                              return (
                                <div className="flex flex-col items-center text-center animate-in fade-in zoom-in duration-700">
                                  <div className="w-20 h-20 rounded-full bg-black flex items-center justify-center mb-6">
                                    <svg
                                      className="w-10 h-10 text-white"
                                      fill="none"
                                      stroke="currentColor"
                                      viewBox="0 0 24 24"
                                    >
                                      <path
                                        strokeLinecap="round"
                                        strokeLinejoin="round"
                                        strokeWidth={2}
                                        d="M5 13l4 4L19 7"
                                      />
                                    </svg>
                                  </div>
                                  <h3 className="text-2xl font-bold text-gray-900">
                                    Exam Fully Completed
                                  </h3>
                                  <p className="text-gray-500 mt-2">
                                    All your sections have been successfully submitted.
                                  </p>
                                </div>
                              );
                            })()}
                          </div>
                        </div>
                      </div>
                    )}

                    {(selectedSection === "READING" || selectedSection === "LISTENING" || selectedSection === "WRITING") && (
                      <div className="mt-2 mb-16 w-full">
                        <div className="bg-white rounded-3xl border border-gray-100 p-6 shadow-sm">
                          <div className="flex items-center justify-between gap-4">
                            <h3 className="text-xl font-bold text-gray-900">
                              {selectedSection === "READING" && "Reading Tests"}
                              {selectedSection === "LISTENING" && "Listening Tests"}
                              {selectedSection === "WRITING" && "Writing Tests"}
                            </h3>
                            <p className="text-sm text-gray-500">
                              {filteredDisplayAssignments.length} total
                            </p>
                          </div>

                          <div className="mt-6 space-y-4">
                            {filteredDisplayAssignments.map((item) => {
                              const hasScore =
                                item.status === "SUBMITTED" &&
                                typeof item.score === "number" &&
                                item.score > 0;
                              const itemTier = getDisplayItemTier(item);
                              const badgeTier: AccessTier =
                                selectedPlan === "PREMIUM" ? "PREMIUM" : itemTier;
                              const requiresUpgrade = !canAccessTier(itemTier);

                              return (
                                <div
                                  key={item.id}
                                  className="rounded-2xl border border-gray-100 p-4"
                                >
                                  <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
                                    <div>
                                      <div className="flex flex-wrap items-center gap-2">
                                        <p className="text-xs font-semibold uppercase tracking-widest text-gray-400">
                                          {selectedSection}
                                        </p>
                                        <span
                                          className={`inline-flex rounded-lg px-2.5 py-1 text-[11px] font-semibold uppercase tracking-wide ${badgeTier === "FREE"
                                            ? "bg-emerald-100 text-emerald-700"
                                            : badgeTier === "GOLD"
                                              ? "bg-sky-100 text-sky-700"
                                              : "bg-amber-100 text-amber-700"
                                            }`}
                                        >
                                          {badgeTier === "GOLD" ? "STANDARD" : badgeTier}
                                        </span>
                                        {item.isPart && (
                                          <span className="inline-flex rounded-lg bg-blue-100 px-2.5 py-1 text-[11px] font-semibold uppercase tracking-wide text-blue-700">
                                            {selectedSection === "LISTENING" ? "Section" : "Part"} {item.partInfo?.part}
                                          </span>
                                        )}
                                        {item.isTask && (
                                          <span className="inline-flex rounded-lg bg-purple-100 px-2.5 py-1 text-[11px] font-semibold uppercase tracking-wide text-purple-700">
                                            Task {item.taskInfo?.task}
                                          </span>
                                        )}
                                      </div>
                                      <h4 className="mt-1 text-lg font-semibold text-gray-900">
                                        {item.displaySection.title}
                                      </h4>
                                      <div className="mt-2 flex flex-wrap items-center gap-3 text-xs text-gray-500">
                                        <span>
                                          {item.isPart
                                            ? `${item.partInfo?.duration} mins · ${item.partInfo?.questionCount} questions`
                                            : item.isTask
                                              ? `${item.taskInfo?.duration} mins · 1 task`
                                              : `${item.displaySection.duration} mins · Full Test`}
                                        </span>
                                        <span>{formatAssignmentDate(item.createdAt)}</span>
                                      </div>
                                    </div>

                                    <div className="flex flex-wrap items-center gap-3">
                                      {hasScore && (
                                        <span className="inline-flex rounded-lg bg-gray-100 px-2.5 py-1 text-xs font-semibold text-gray-700">
                                          Score: {Number(item.score).toFixed(1)}
                                        </span>
                                      )}

                                      {requiresUpgrade ? (
                                        <button
                                          type="button"
                                          onClick={() => {
                                            const originalAssignment = assignments.find(
                                              (a) => a.id === item.originalAssignmentId
                                            );
                                            if (originalAssignment) {
                                              handlePremiumLockedClick(
                                                originalAssignment,
                                                itemTier === "GOLD" ? "GOLD" : "PREMIUM",
                                              );
                                            }
                                          }}
                                          className="inline-flex rounded-lg bg-amber-500 px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-amber-600"
                                        >
                                          {itemTier === "GOLD" ? "Unlock Standard" : "Unlock Premium"}
                                        </button>
                                      ) : (
                                        <Link
                                          href={`/exam/${item.id}`}
                                          onClick={(event) => {
                                            const isNonFree = itemTier !== "FREE";
                                            handleStartExamClick(event, item.id, isNonFree, isNonFree);
                                          }}
                                          className="inline-flex rounded-lg bg-black px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-gray-800"
                                        >
                                          {getActionLabel(item.status, false)}
                                        </Link>
                                      )}
                                    </div>
                                  </div>
                                </div>
                              );
                            })}
                          </div>
                        </div>
                      </div>
                    )}

                  </>
                )}
              </>
            )}
          </div>
        </div>
      </main>

      <ConfirmationModal
        isOpen={isLogoutModalOpen}
        onClose={() => setIsLogoutModalOpen(false)}
        onConfirm={logout}
        title="Sign Out"
        message="Are you sure you want to sign out?"
        confirmText="Sign Out"
        variant="danger"
      />
    </div>
  );
}
